-- A budget (hub stored-types.ts `WorkBudget`) is four columns on each of
-- `projects`, `routines` and `work_items`, not JSON: `budget_usd`,
-- `budget_turns`, `budget_minutes`, and `budget_unread`.
--
-- Each limit null is "not set here", the value every writer meant by null
-- (or by `{}`, or a limit left out): a work item's budget was taken limit by
-- limit from its call, task or routine, then its project, when it was made
-- (work-items.ts `budgetFrom`), so the end of that chain is no limit, as
-- before. A limit that reads (dollars above 0; turns and minutes whole
-- numbers from 1, as work-limits.ts `budgetProblem` let every writer write)
-- is placed in its column.
--
-- A budget that is stored and does not read whole (not JSON, not an object,
-- a key that is not usd, turns or minutes, or a limit that is not a number
-- in its range) is never read as no limit: it is kept as it was stored in
-- `budget_unread`, its limits that read placed beside it, and while it is
-- set the work it governs stops (a work item is stopped, a project starts
-- no work item, a routine skips its runs). The step before this migration
-- (db/migrate.ts `budget-unread`) logs each such row by its id and reason.
ALTER TABLE `projects` ADD `budget_usd` real;--> statement-breakpoint
ALTER TABLE `projects` ADD `budget_turns` integer;--> statement-breakpoint
ALTER TABLE `projects` ADD `budget_minutes` integer;--> statement-breakpoint
ALTER TABLE `projects` ADD `budget_unread` text;--> statement-breakpoint
ALTER TABLE `routines` ADD `budget_usd` real;--> statement-breakpoint
ALTER TABLE `routines` ADD `budget_turns` integer;--> statement-breakpoint
ALTER TABLE `routines` ADD `budget_minutes` integer;--> statement-breakpoint
ALTER TABLE `routines` ADD `budget_unread` text;--> statement-breakpoint
ALTER TABLE `work_items` ADD `budget_usd` real;--> statement-breakpoint
ALTER TABLE `work_items` ADD `budget_turns` integer;--> statement-breakpoint
ALTER TABLE `work_items` ADD `budget_minutes` integer;--> statement-breakpoint
ALTER TABLE `work_items` ADD `budget_unread` text;--> statement-breakpoint
UPDATE `projects` SET `budget_usd` = CASE WHEN CASE WHEN json_valid(`budget`) THEN json_type(`budget`) = 'object' AND json_type(`budget`, '$.usd') IN ('integer', 'real') AND json_extract(`budget`, '$.usd') > 0 ELSE 0 END THEN json_extract(`budget`, '$.usd') END, `budget_turns` = CASE WHEN CASE WHEN json_valid(`budget`) THEN json_type(`budget`) = 'object' AND json_type(`budget`, '$.turns') IN ('integer', 'real') AND json_extract(`budget`, '$.turns') >= 1 AND json_extract(`budget`, '$.turns') = CAST(json_extract(`budget`, '$.turns') AS INTEGER) ELSE 0 END THEN CAST(json_extract(`budget`, '$.turns') AS INTEGER) END, `budget_minutes` = CASE WHEN CASE WHEN json_valid(`budget`) THEN json_type(`budget`) = 'object' AND json_type(`budget`, '$.minutes') IN ('integer', 'real') AND json_extract(`budget`, '$.minutes') >= 1 AND json_extract(`budget`, '$.minutes') = CAST(json_extract(`budget`, '$.minutes') AS INTEGER) ELSE 0 END THEN CAST(json_extract(`budget`, '$.minutes') AS INTEGER) END, `budget_unread` = CASE WHEN ((`budget` IS NULL OR CASE WHEN json_valid(`budget`) THEN json_type(`budget`) = 'null' ELSE 0 END) OR CASE WHEN json_valid(`budget`) THEN json_type(`budget`) = 'object' AND NOT EXISTS (SELECT 1 FROM json_each(`budget`) WHERE `key` NOT IN ('usd', 'turns', 'minutes')) AND (json_type(`budget`, '$.usd') IS NULL OR (json_type(`budget`, '$.usd') IN ('integer', 'real') AND json_extract(`budget`, '$.usd') > 0)) AND (json_type(`budget`, '$.turns') IS NULL OR (json_type(`budget`, '$.turns') IN ('integer', 'real') AND json_extract(`budget`, '$.turns') >= 1 AND json_extract(`budget`, '$.turns') = CAST(json_extract(`budget`, '$.turns') AS INTEGER))) AND (json_type(`budget`, '$.minutes') IS NULL OR (json_type(`budget`, '$.minutes') IN ('integer', 'real') AND json_extract(`budget`, '$.minutes') >= 1 AND json_extract(`budget`, '$.minutes') = CAST(json_extract(`budget`, '$.minutes') AS INTEGER))) ELSE 0 END) THEN NULL ELSE `budget` END WHERE `budget` IS NOT NULL;--> statement-breakpoint
